def problem_014(upper_bound: int = 1_000_000) -> int:





    max_len = 0
    result = 0
    for i in range(1, upper_bound):
        collatz_len_i = collatz_sequence_len(i)
        if collatz_len_i > max_len:
            max_len = collatz_len_i
            result = i
    return result


def collatz_sequence_len(n: int) -> int:





    result = 1
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        result += 1
    return result
